export class LeaderboardEntryDto implements ILeaderboardEntryDto {
    rank!: number;
    userId!: number;
    displayName!: string | undefined;
    score!: number;
    updatedAt!: moment.Moment;

    constructor(data?: ILeaderboardEntryDto) {
        if (data) {
            for (var property in data) {
                if (data.hasOwnProperty(property))
                    (<any>this)[property] = (<any>data)[property];
            }
        }
    }

    init(_data?: any) {
        if (_data) {
            this.rank = _data["rank"];
            this.userId = _data["userId"];
            this.displayName = _data["displayName"];
            this.score = _data["score"];
            this.updatedAt = _data["updatedAt"] ? moment(_data["updatedAt"].toString()) : <any>undefined;
        }
    }

    static fromJS(data: any): LeaderboardEntryDto {
        data = typeof data === 'object' ? data : {};
        let result = new LeaderboardEntryDto();
        result.init(data);
        return result;
    }

    toJSON(data?: any) {
        data = typeof data === 'object' ? data : {};
        data["rank"] = this.rank;
        data["userId"] = this.userId;
        data["displayName"] = this.displayName;
        data["score"] = this.score;
        data["updatedAt"] = this.updatedAt ? this.updatedAt.toISOString() : <any>undefined;
        return data;
    }
}

