export enum RankedQueueStatus {
    Waiting = 0,
    Matched = 1,
    Cancelled = 2,
    Abandoned = 3,
}

export class RankedStatusDto implements IRankedStatusDto {
    rating!: number;
    gamesPlayed!: number;
    wins!: number;
    losses!: number;
    draws!: number;
    queue!: RankedQueueDto;
    recentMatches!: MatchHistoryDto[] | undefined;

    constructor(data?: IRankedStatusDto) {
        if (data) {
            for (var property in data) {
                if (data.hasOwnProperty(property))
                    (<any>this)[property] = (<any>data)[property];
            }
        }
    }

    init(_data?: any) {
        if (_data) {
            this.rating = _data["rating"];
            this.gamesPlayed = _data["gamesPlayed"];
            this.wins = _data["wins"];
            this.losses = _data["losses"];
            this.draws = _data["draws"];
            this.queue = _data["queue"] ? RankedQueueDto.fromJS(_data["queue"]) : <any>undefined;
            if (Array.isArray(_data["recentMatches"])) {
                this.recentMatches = [] as any;
                for (let item of _data["recentMatches"])
                    this.recentMatches!.push(MatchHistoryDto.fromJS(item));
            }
        }
    }

    static fromJS(data: any): RankedStatusDto {
        data = typeof data === 'object' ? data : {};
        let result = new RankedStatusDto();
        result.init(data);
        return result;
    }

    toJSON(data?: any) {
        data = typeof data === 'object' ? data : {};
        data["rating"] = this.rating;
        data["gamesPlayed"] = this.gamesPlayed;
        data["wins"] = this.wins;
        data["losses"] = this.losses;
        data["draws"] = this.draws;
        data["queue"] = this.queue ? this.queue.toJSON() : <any>undefined;
        if (Array.isArray(this.recentMatches)) {
            data["recentMatches"] = [];
            for (let item of this.recentMatches)
                data["recentMatches"].push(item.toJSON());
        }
        return data;
    }
}

export interface IRankedStatusDto {
    rating: number;
    gamesPlayed: number;
    wins: number;
    losses: number;
    draws: number;
    queue: RankedQueueDto;
    recentMatches: MatchHistoryDto[] | undefined;
}

